CREATE DATABASE IF NOT EXISTS resumeiq CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE resumeiq;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'admin',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,type VARCHAR(60) NOT NULL,url VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS candidates (id VARCHAR(32) PRIMARY KEY,job_id BIGINT UNSIGNED NULL,name VARCHAR(160) NOT NULL,role_title VARCHAR(160) NOT NULL DEFAULT 'Candidate',email VARCHAR(190) NULL,phone VARCHAR(60) NULL,country_code CHAR(2) NULL,country_name VARCHAR(100) NULL,score SMALLINT UNSIGNED NOT NULL DEFAULT 0,stage VARCHAR(30) NOT NULL DEFAULT 'Applied',source_name VARCHAR(160) NOT NULL DEFAULT 'Direct upload',skills_json JSON NULL,experience_json JSON NULL,analysis_json JSON NULL,source_url VARCHAR(1000) NULL,stored_file VARCHAR(255) NULL,created_at DATETIME NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_job(job_id),INDEX idx_stage(stage),INDEX idx_score(score),INDEX idx_email(email),INDEX idx_country(country_code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,external_id BIGINT NULL UNIQUE,title VARCHAR(180) NOT NULL,description MEDIUMTEXT NOT NULL,public_url VARCHAR(1000) NULL,location VARCHAR(180) NULL,employment_type VARCHAR(80) NULL,min_experience DECIMAL(4,1) NULL,max_experience DECIMAL(4,1) NULL,minimum_commitment_months SMALLINT UNSIGNED NULL,required_skills_json JSON NULL,preferred_skills_json JSON NULL,status VARCHAR(30) NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS integrations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(60) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL DEFAULT 'disconnected',config_json JSON NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS organization_settings (id TINYINT UNSIGNED PRIMARY KEY,name VARCHAR(160) NOT NULL DEFAULT 'ResumeIQ',domain VARCHAR(255) NULL,logo_path VARCHAR(255) NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_reset_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_reset_expiry(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wishlist_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,required_skills_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_wishlist_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE KEY uniq_user_profile(user_id,name),INDEX idx_profile_job(job_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wishlist_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,profile_id BIGINT UNSIGNED NOT NULL,candidate_id VARCHAR(32) NOT NULL,disposition VARCHAR(30) NOT NULL DEFAULT 'wishlist',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_wishlist_profile FOREIGN KEY(profile_id) REFERENCES wishlist_profiles(id) ON DELETE CASCADE,UNIQUE KEY uniq_profile_candidate(profile_id,candidate_id),INDEX idx_wishlist_disposition(profile_id,disposition)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS email_batches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,profile_id BIGINT UNSIGNED NULL,subject VARCHAR(255) NOT NULL,body TEXT NOT NULL,interview_at DATETIME NULL,timezone VARCHAR(80) NULL,recipient_count INT UNSIGNED NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'preview',dedupe_key CHAR(64) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_email_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_email_profile FOREIGN KEY(profile_id) REFERENCES wishlist_profiles(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS email_recipients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,candidate_id VARCHAR(32) NOT NULL,email VARCHAR(190) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',sent_at DATETIME NULL,error_text VARCHAR(500) NULL,CONSTRAINT fk_recipient_batch FOREIGN KEY(batch_id) REFERENCES email_batches(id) ON DELETE CASCADE,UNIQUE KEY uniq_batch_candidate(batch_id,candidate_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS interview_invite_locks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,profile_id BIGINT UNSIGNED NOT NULL,candidate_id VARCHAR(32) NOT NULL,batch_id BIGINT UNSIGNED NULL,active TINYINT(1) NOT NULL DEFAULT 1,locked_at DATETIME NOT NULL,reset_at DATETIME NULL,reset_by BIGINT UNSIGNED NULL,CONSTRAINT fk_invite_lock_profile FOREIGN KEY(profile_id) REFERENCES wishlist_profiles(id) ON DELETE CASCADE,CONSTRAINT fk_invite_lock_batch FOREIGN KEY(batch_id) REFERENCES email_batches(id) ON DELETE SET NULL,CONSTRAINT fk_invite_lock_reset_user FOREIGN KEY(reset_by) REFERENCES users(id) ON DELETE SET NULL,UNIQUE KEY uniq_profile_invite_candidate(profile_id,candidate_id),INDEX idx_invite_locks_active(profile_id,active)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(50) NOT NULL,entity_id VARCHAR(64) NULL,metadata_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_audit_entity(entity_type,entity_id),INDEX idx_audit_created(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS interview_batches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_id BIGINT UNSIGNED NOT NULL,profile_id BIGINT UNSIGNED NULL,email_batch_id BIGINT UNSIGNED NULL,created_by BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,availability_start DATE NOT NULL,availability_end DATE NOT NULL,daily_start TIME NOT NULL,daily_end TIME NOT NULL,slot_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 30,buffer_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 0,timezone VARCHAR(80) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_interview_batch_job FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE RESTRICT,CONSTRAINT fk_interview_batch_profile FOREIGN KEY(profile_id) REFERENCES wishlist_profiles(id) ON DELETE SET NULL,CONSTRAINT fk_interview_batch_email FOREIGN KEY(email_batch_id) REFERENCES email_batches(id) ON DELETE SET NULL,CONSTRAINT fk_interview_batch_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX idx_interview_batch_window(availability_start,availability_end),INDEX idx_interview_batch_job_status(job_id,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS interview_invitations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,candidate_id VARCHAR(32) NOT NULL,email_recipient_id BIGINT UNSIGNED NULL,token_hash CHAR(64) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL DEFAULT 'draft',recipient_email VARCHAR(190) NOT NULL,subject VARCHAR(255) NOT NULL,html_snapshot MEDIUMTEXT NOT NULL,sent_at DATETIME NULL,expires_at DATETIME NOT NULL,confirmed_slot_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_interview_invitation_batch FOREIGN KEY(batch_id) REFERENCES interview_batches(id) ON DELETE CASCADE,CONSTRAINT fk_interview_invitation_candidate FOREIGN KEY(candidate_id) REFERENCES candidates(id) ON DELETE RESTRICT,CONSTRAINT fk_interview_invitation_recipient FOREIGN KEY(email_recipient_id) REFERENCES email_recipients(id) ON DELETE SET NULL,UNIQUE KEY uniq_interview_batch_candidate(batch_id,candidate_id),INDEX idx_interview_invitation_status(status,expires_at),INDEX idx_interview_invitation_candidate(candidate_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS interview_slots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'available',invitation_id BIGINT UNSIGNED NULL,reserved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_interview_slot_batch FOREIGN KEY(batch_id) REFERENCES interview_batches(id) ON DELETE CASCADE,CONSTRAINT fk_interview_slot_invitation FOREIGN KEY(invitation_id) REFERENCES interview_invitations(id) ON DELETE SET NULL,UNIQUE KEY uniq_interview_batch_start(batch_id,starts_at),INDEX idx_interview_slot_status(batch_id,status,starts_at)) ENGINE=InnoDB;
ALTER TABLE interview_invitations ADD CONSTRAINT fk_interview_invitation_slot FOREIGN KEY(confirmed_slot_id) REFERENCES interview_slots(id) ON DELETE SET NULL,ADD COLUMN notification_status VARCHAR(30) NOT NULL DEFAULT 'not_sent',ADD COLUMN notification_sent_at DATETIME NULL,ADD COLUMN notification_error VARCHAR(500) NULL,ADD COLUMN outcome VARCHAR(30) NULL,ADD COLUMN outcome_at DATETIME NULL,ADD COLUMN outcome_by BIGINT UNSIGNED NULL,ADD COLUMN outcome_notes VARCHAR(1000) NULL,ADD INDEX idx_interview_invitation_outcome(outcome,outcome_at),ADD CONSTRAINT fk_interview_invitation_outcome_user FOREIGN KEY(outcome_by) REFERENCES users(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS interview_outcome_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invitation_id BIGINT UNSIGNED NOT NULL,candidate_id VARCHAR(32) NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,outcome VARCHAR(30) NOT NULL,notes VARCHAR(1000) NULL,previous_outcome VARCHAR(30) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_interview_outcome_invitation FOREIGN KEY(invitation_id) REFERENCES interview_invitations(id) ON DELETE CASCADE,CONSTRAINT fk_interview_outcome_candidate FOREIGN KEY(candidate_id) REFERENCES candidates(id) ON DELETE RESTRICT,CONSTRAINT fk_interview_outcome_actor FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT,INDEX idx_interview_outcome_candidate(candidate_id,created_at),INDEX idx_interview_outcome_invitation(invitation_id,created_at)) ENGINE=InnoDB;
